function Owned($tool,[string[]]$argv,[string]$suffix){
  $p=Join-Path $logs ($tag+'_'+$suffix+'.call.json');$log=Join-Path $logs ($tag+'_'+$suffix+'.log');Fresh @($p,$log);V @($tool);[IO.File]::WriteAllBytes($log,[byte[]]@());$code=$null;$failure=$null;$started=[DateTime]::UtcNow.ToString('o');$prior=$ErrorActionPreference;Push-Location $src
  try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $tool.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$failure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$prior}
  Save $p ([ordered]@{program=$tool;arguments=$argv;working_directory=$src;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$failure;log=(E $log);build_tool_only=$true;program_run=$false;physical_acceptance=$false});return (E $p)
}
Need $ExecutionAuthorized.IsPresent 'Root full read and explicit compile/link authorization required';Fresh @($folder,$record)
