foreach($pair in @($b.documentation_snapshot,$b.case_readme_snapshot)){Need ($pair.original.bytes -eq $pair.snapshot.bytes -and $pair.original.sha256 -ieq $pair.snapshot.sha256) 'Recorded doc/README pair differed as of build'}
$names=@(Get-ChildItem -LiteralPath $snapshotRoot -File|Where-Object{$_.Extension -in @('.cpp','.h','.cu','.cuh')}|ForEach-Object{$_.FullName});Need ($names.Count -eq 265 -and !(Compare-Object ($names|Sort-Object) ($snapshots.path|Sort-Object))) 'Archived265 code membership differs'
$authors=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_cryer_gpu_component_build_r2.json')),(E $cpp),(E (Join-Path $tests 'notes\upl_cryer_gpu_component_r2.json')),(E $neutral),(E (Join-Path $case02 'notes\upl_cpu_public_native_r1.json')));Need ((E $neutral).sha256 -ceq '9f6668bfe3d1bbcca7c45c58809f7062c21fcb46baae76f0a2a1b0ef3ca56d38') 'Immutable neutral source changed'
$objects=@($b.objects|Where-Object{[IO.Path]::GetFileName($_.path) -ine 'main.obj'});$byName=@{};foreach($e in $objects){$key=[IO.Path]::GetFileName($e.path).ToLowerInvariant();Need (!$byName.ContainsKey($key)) 'Duplicate retained object basename';$byName[$key]=$e};Need ($objects.Count -eq 110 -and $byName.Count -eq 110) 'Exact110 retained non-main objects required'
$environmentE=E $b.environment.path;$environment=J $environmentE.path;$selected=[ordered]@{};Need ($environment.exit_code -eq 0 -and $environment.typed_LASTEXITCODE_captured_immediately -and $environment.owned_call_exited) 'Retained environment failed';foreach($key in @('INCLUDE','LIB','VCToolsInstallDir','WindowsSdkDir','WindowsSDKVersion')){$value=[string]$environment.selected.$key;Need (![string]::IsNullOrWhiteSpace($value)) ('Missing environment '+$key);$selected[$key]=$value}
$bindings=@($environmentE,$environment.program,$environment.script,$buildE,$b.project_call,$b.program,$b.log,$b.binlog,$recipeE,$h.compile_call,$h.link_call,$cc.program,$cc.log,$lc.program,$lc.log,$b.documentation_snapshot.snapshot,$b.case_readme_snapshot.snapshot)+$authors+$snapshots+@($b.objects)+@($h.tools)+@($b.tools)+@($h.libraries)
foreach($pair in $b.runtime){Need ($pair.original.bytes -eq $pair.copy.bytes -and $pair.original.sha256 -ieq $pair.copy.sha256) 'Recorded runtime copy differed as of build';$bindings+=@($pair.copy)} # Copies only; do not recheck canonical runtime originals.
$oldCpp=Join-Path $case02 'support\upl_gravity_periodic_gpu_r1.cpp';$liveInclude='/I'+(Join-Path $src 'source');$compile=@();$cs=0;$fo=0;$fd=0;$inc=0
