$compile+=@('/sourceDependencies',$deps)
$runtimeFlag=if($Configuration -ceq 'Debug'){'/MTd'}else{'/MT'};Need ($cs -eq 1 -and $fo -eq 1 -and $fd -eq 1 -and $inc -eq 1 -and @($compile|Where-Object{$_.StartsWith('/I',[StringComparison]::OrdinalIgnoreCase)}).Count -eq 2 -and $compile -ccontains '/D_WITHGPU' -and $compile -ccontains $runtimeFlag -and $compile -ccontains '/fp:precise' -and $compile -ccontains '/std:c++17') 'Only CPP/Fo/Fd/one archived-header remap plus dependency output permitted; CUDA include unchanged'
$link=@();$maps=@();$hh=0;$oo=0;$pd=0
$search=@($lc.arguments|Where-Object{$_.StartsWith('/LIBPATH:',[StringComparison]::OrdinalIgnoreCase)}|ForEach-Object{$_.Substring(9)})+@(([string]$selected.LIB).Split(';')|Where-Object{$_});$resolvedLibraries=@()
foreach($a in $lc.arguments){if($a -ieq $h.helper_object.path){$link+=$obj;$hh++}elseif($a.StartsWith('/OUT:',[StringComparison]::OrdinalIgnoreCase)){$link+='/OUT:'+$exe;$oo++}elseif($a.StartsWith('/PDB:',[StringComparison]::OrdinalIgnoreCase)){$link+='/PDB:'+(Join-Path $folder 'link.pdb');$pd++}elseif($a.EndsWith('.obj',[StringComparison]::OrdinalIgnoreCase)){$name=[IO.Path]::GetFileName($a).ToLowerInvariant();Need ($byName.ContainsKey($name)) 'Unknown recipe object';$link+=$byName[$name].path;$maps+=@{old_recipe_object=$a;retained=$byName[$name]}}elseif($a.EndsWith('.lib',[StringComparison]::OrdinalIgnoreCase)){$resolved=$null;if([IO.Path]::IsPathRooted($a)){if(Test-Path -LiteralPath $a){$resolved=$a}}else{foreach($dir in $search){$p=Join-Path $dir $a;if(Test-Path -LiteralPath $p){$resolved=$p;break}}};Need ($null -ne $resolved) ('Unresolved selected library '+$a);$libE=E $resolved;$resolvedLibraries+=@($libE);$link+=$libE.path}else{$link+=$a}}
$linked=@($link|Where-Object{$_.EndsWith('.obj',[StringComparison]::OrdinalIgnoreCase)});$libs=@($link|Where-Object{$_.EndsWith('.lib',[StringComparison]::OrdinalIgnoreCase)});$libraryNames=@($resolvedLibraries.path);$expectedPdb=if($Configuration -ceq 'Debug'){1}else{0}
Need ($hh -eq 1 -and $oo -eq 1 -and $pd -eq $expectedPdb -and $maps.Count -eq 110 -and $linked.Count -eq 111 -and @($linked|Sort-Object -Unique).Count -eq 111 -and !(Compare-Object ($linked|Sort-Object) ((@($objects.path)+@($obj))|Sort-Object)) -and $libs.Count -eq 18 -and ($libs -join [char]0) -ieq ($libraryNames -join [char]0)) 'Exact110+1 link/ordered18 resolved library closure required'
Need ($resolvedLibraries.Count -eq 18) 'Expected selected6 project/CUDA and12 SDK libraries'
foreach($e in $h.libraries){$matches=@($resolvedLibraries|Where-Object{[IO.Path]::GetFileName($_.path) -ieq [IO.Path]::GetFileName($e.path)});Need ($matches.Count -eq 1 -and $matches[0].bytes -eq $e.bytes -and $matches[0].sha256 -ieq $e.sha256) 'Known recipe library resolution differs'}
$bindings+=@($resolvedLibraries)
V $bindings;foreach($key in $selected.Keys){[Environment]::SetEnvironmentVariable($key,[string]$selected[$key],'Process')};$env:PATH=[IO.Path]::GetDirectoryName($cc.program.path)+';'+$env:PATH
[void](New-Item -ItemType Directory -Path $folder);$compileCall=$null;$linkCall=$null;$program=$null;$helperObject=$null;$dependency=$null;$projectHeaders=@();$runtime=@();$artifacts=@();$failure=$null
