}catch{$failure=$_.Exception.Message}
$unchanged=$false;try{$post=$bindings+@($projectHeaders)+$artifacts;foreach($e in @($helperObject,$dependency,$program,$compileCall,$linkCall)){if($e){$post+=@($e)}};foreach($pair in $runtime){$post+=@($pair.original,$pair.copy)};FinalV $post;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
